final class ReticulumStampTests: XCTestCase {
    func testWorkblockSaltUsesMsgPackIntegersLikeLXMF() {
        let material = rnsHex(LXStamperVectors.saltMaterial)
        for (round, packed, salt) in LXStamperVectors.packed {
            let encoded = ReticulumMsgPackWriter().integer(Int64(round)).bytes
            XCTAssertEqual(ReticulumWire.hex(encoded), packed, "msgpack of \(round)")
            XCTAssertEqual(ReticulumWire.hex(ReticulumWire.fullHash(material + encoded)), salt, "salt of \(round)")
        }
    }

    func testMessageIdWorkblockAndStampValuesMatchLXStamper() throws {
        var pairs = 0
        var edges = Set<Int>()
        for (dest, source, timestamp, title, content, messageId, workblockHash, stamps) in LXStamperVectors.messages {
            let text = String(decoding: rnsHex(content), as: UTF8.self)
            let payload = ReticulumLxmf.payload(timestamp: timestamp, title: title, content: text)
            XCTAssertEqual(payload[1], 0xcb)
            let id = ReticulumLxmf.messageId(destination: rnsHex(dest), source: rnsHex(source), payload: payload)
            XCTAssertEqual(ReticulumWire.hex(id), messageId, "message id for \(title)")
            let block = ReticulumLxmf.workblock(id, rounds: ReticulumLxmf.stampRounds)
            XCTAssertEqual(block.count, 768_000)
            XCTAssertEqual(ReticulumWire.hex(ReticulumWire.fullHash(block)), workblockHash, "workblock for \(title)")
            var midstate = ReticulumSha256()
            midstate.absorbBlocks(block)
            for (stampHex, value) in stamps {
                let stamp = rnsHex(stampHex)
                let digest = ReticulumWire.fullHash(block + stamp)
                XCTAssertEqual(midstate.finish(stamp), digest)
                XCTAssertEqual(ReticulumLxmf.stampValue(workblock: block, stamp: stamp), value, stampHex)
                XCTAssertEqual(ReticulumLxmf.leadingZeroBits(digest), value, stampHex)
                if digest[0] == 0 || digest[0] == 0x80 || digest[0] == 0x7f || digest[0] == 0x01 || digest[0] == 0xff { edges.insert(Int(digest[0]) << 8 | Int(digest[1])) }
                pairs += 1
            }
        }
        XCTAssertGreaterThanOrEqual(pairs, 300)
        XCTAssertTrue(edges.contains(0x0080) && edges.contains(0x0001) && edges.contains { $0 >> 8 == 0 && $0 & 0xff == 0 })
    }

    func testGeneratedStampsPassLXMFValidation() throws {
        let (dest, source, timestamp, title, content, messageId, _, _) = LXStamperVectors.messages[1]
        let payload = ReticulumLxmf.payload(timestamp: timestamp, title: title, content: String(decoding: rnsHex(content), as: UTF8.self))
        let id = ReticulumLxmf.messageId(destination: rnsHex(dest), source: rnsHex(source), payload: payload)
        XCTAssertEqual(ReticulumWire.hex(id), messageId)
        let block = ReticulumLxmf.workblock(id, rounds: ReticulumLxmf.stampRounds)
        for cost in [1, 8, 12] {
            let generated = try XCTUnwrap(ReticulumLxmf.generateStamp(messageId: id, cost: cost))
            let digest = ReticulumWire.fullHash(block + generated.stamp)
            XCTAssertGreaterThanOrEqual(ReticulumLxmf.leadingZeroBits(digest), cost)
            XCTAssertEqual(ReticulumLxmf.leadingZeroBits(digest), generated.value)
            var target = [UInt8](repeating: 0, count: 32)
            target[(cost - 1) / 8] = UInt8(0x80 >> ((cost - 1) % 8))
            XCTAssertFalse(target.lexicographicallyPrecedes(digest), "LXStamper.stamp_valid: int(digest) <= 2^(256 - cost)")
        }
        let sender = ReticulumIdentity.generate()
        let stamped = try XCTUnwrap(ReticulumLxmf.pack(source: sender, sourceHash: rnsHex(source), destinationHash: rnsHex(dest), timestamp: timestamp,
                                                        title: title, content: String(decoding: rnsHex(content), as: UTF8.self), stamp: [UInt8](repeating: 7, count: 32)))
        let unpacked = try ReticulumLxmf.unpack(stamped.packed)
        XCTAssertEqual(ReticulumWire.hex(unpacked.hash), messageId)
        XCTAssertEqual(unpacked.stamp, [UInt8](repeating: 7, count: 32))
    }
}
